select location, case when budget >= 4466000 then 'high' when budget >= 1076000 then 'mid' else 'low' end as budget_bucket, round((100 * sum(case when location = 'Chiang Mai' then 1 else 0 end)) / count(*), 1) as pct_chiang_mai, round(avg(budget), 2) as avg_budget, round((100 * sum(case when location = 'New York' then 1 else 0 end)) / count(*), 1) as pct_new_york from departments group by 1, 2 having round((100 * sum(case when location = 'New York' then 1 else 0 end)) / count(*), 1) < 76
